use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let hex_input = input.as_str().unwrap_or_default();
    let mut bytes = Vec::new();
    let mut i = 0;

    while i < hex_input.len() {
        let byte = hex_input[i..i + 2].parse::<u8>().unwrap_or(0);
        bytes.push(byte);
        i += 2;
    }

    if bytes.len() % 2 != 0 {
        bytes.push(0);
    }

    serde_json::Value::Array(bytes)
}
